class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        int m = nums1.size();
        int n = nums2.size();
        int x = m + n;

        int t = (x % 2 == 0) ? 1 : -1; // Determine if the total length is even or odd

        int y = 0; // Counter for merged elements
        int i = 0; // Pointer for nums1
        int j = 0; // Pointer for nums2
        int q1, q2; // Values for calculating the median

        while (y <= x / 2) {
            q1 = q2; // Store the previous value of q2

            if (i < m && (j >= n || nums1[i] <= nums2[j])) {
                q2 = nums1[i];
                i++;
            } else {
                q2 = nums2[j];
                j++;
            }

            y++;
        }

        if (t == 1) {
            return (q1 + q2) / 2.0; // Return the average of q1 and q2
        } else {
            return q2; // Return the value of q2
        }
    }
};
