class Solution {
public:
    int n;  
    set<vector<int>> ans;
    void f(int i, vector<int>& nums){
        if (i==n){// reach the end of nums
            ans.insert(nums);
            return ;
        } 
        f(i+1, nums);
        for (int j=i+1; j<n; j++){
            if (nums[i]!=nums[j]){
                swap(nums[i], nums[j]);
                f(i+1, nums);
                swap(nums[i], nums[j]);
            } 
        }
    }    
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        n=nums.size();
        sort(nums.begin(), nums.end());
        f(0, nums);
        return vector<vector<int>>(ans.begin(), ans.end());
    }
};,49,https://leetcode.com/problems/permutations-ii,https://leetcode.com/problems/permutations-ii/solutions/3860836/c-2-backtrackings-frequency-set-swap/,23,47,cpp

class Solution {
  public List<List<String>> groupAnagrams(String[] strs) {

        HashMap<String,List<String>> map=new HashMap<>();

        List<List<String>> result = new ArrayList<>();


        for (String word: strs
        ) {
            char[] charArray = word.toCharArray();


            Arrays.sort(charArray);

            String sortedWord = String.valueOf(charArray);

            if (!map.containsKey(sortedWord)) {
                map.put(sortedWord, new ArrayList<>());
            }


            map.get(sortedWord).add(word);


        }
        result.addAll(map.values());

        return result;
    }
