class Solution {
private:

    int solveMemoization(int m, int n, vector<vector<int>> &dp)
    {
        if(m==0 && n==0)
            return 1;

        if(m<0 || n<0)
            return 0;

        if(dp[m][n] != -1)
            return dp[m][n];

        int first = solveMemoization(m-1, n, dp);
        int second = solveMemoization(m, n-1, dp);

        dp[m][n]=first+second;
        return dp[m][n];
    }

public:
    int uniquePaths(int m, int n) {
        vector<vector<int>> dp(m, vector<int> (n, -1));
        int ans = solveMemoization(m-1, n-1, dp);
        return ans;
    }
