public:
    int solve(int i,int j,string &s, string &t,vector<vector<int>> &dp){
        if(j == 0)
            return 1;
        if(i == 0)
            return 0;
        if(dp[i][j] != -1)
            return dp[i][j];
        if(s[i-1] == t[j-1])
            return dp[i][j] = solve(i-1,j-1,s,t,dp) + solve(i-1,j,s,t,dp);
        else
            return dp[i][j] = solve(i-1,j,s,t,dp);
    }
