class Solution:
    def ncr(self, n, r, dp):
        if r == 0 or r == n:
            return 1
        if r == 1 or r == n - 1:
            return n
        if dp[n][r] != -1:
            return dp[n][r]
        dp[n][r] = self.ncr(n - 1, r, dp) + self.ncr(n - 1, r - 1, dp)
        return dp[n][r]

    def getRow(self, rowIndex):
        ans = []
        dp = [[-1] * (rowIndex + 1) for _ in range(rowIndex + 1)]
        for i in range(rowIndex + 1):
            ans.append(self.ncr(rowIndex, i, dp))
        return ans,102,https://leetcode.com/problems/pascals-triangle-ii,https://leetcode.com/problems/pascals-triangle-ii/solutions/4173639/the-magic-of-pascal-s-triangle-generating-rows-with-ease-mr-robot/,51,119,python

class Solution {
public:
    int minimumTotal(vector<vector<int>>& triangle) {
        int n = triangle.size();
        vector<vector<int>> memo(n, vector<int>(n, -1));
        return dp(triangle, 0, 0, memo);
    }

private:
    int dp(vector<vector<int>>& triangle, int idx, int row, vector<vector<int>>& memo) {
        if (row == triangle.size()) return 0;
        if (memo[row][idx] != -1) return memo[row][idx];

        int down = dp(triangle, idx, row + 1, memo);
        int downRight = dp(triangle, idx + 1, row + 1, memo);
        return memo[row][idx] = triangle[row][idx] + min(down, downRight);
    }
