import java.util.*;

class Pair {
    String values; // Represents the current word in the word ladder
    int count; // Represents the number of steps taken to reach this word

    Pair(String values, int count) {
        this.values = values;
        this.count = count;
    }
}

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Queue<Pair> queue = new LinkedList<>();
        queue.add(new Pair(beginWord, 1)); // Start with the initial word and count it as 1 step

        HashSet<String> wordSet = new HashSet<>(); // To track available words for transformation

        for (int i = 0; i < wordList.size(); i++) {
            wordSet.add(wordList.get(i)); // Populate the word set with the provided word list
        }

        wordSet.remove(beginWord); // Remove the start word from the word set

        while (!queue.isEmpty()) {

            String word = queue.peek().values; // Get the current word from the front of the queue
            int steps = queue.peek().count; // Get the steps taken to reach this word
            queue.remove(); // Dequeue the current word

            if (word.equals(endWord)) {
                return steps; // If the current word matches the end word, return the steps taken
            }

            for (int i = 0; i < word.length(); i++) {
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    char replacedCharArray[] = word.toCharArray();
                    replacedCharArray[i] = ch;

                    // Create a new String representation of the modified character array.
                    // This step is essential because the BFS algorithm explores variations
                    // of words by changing one character at a time, and we need to convert
                    // the character array back into a string to work with it.
                    String replacedWord = new String(replacedCharArray);

                    if (wordSet.contains(replacedWord)) {
                        wordSet.remove(replacedWord); // Remove the word from the set to avoid revisiting
                        queue.add(new Pair(replacedWord, steps + 1)); // Enqueue the transformed word with incremented steps
                    }
                }
            }
        }
        return 0; // If no transformation path is found, return 0
    }
}
