        {
            for (int j = 0; j < grid[0].length; j++)
            {
                if (grid[i][j] == '1')
                    earth.add(new Integer[]{i, j});
            }
        }
        Integer []tmp;
        int ch = 0;
        while (earth.size() > 0)
        {
            tmp = earth.getFirst();
            earth.removeFirst();
            if (grid[tmp[0]][tmp[1]] == '1') {
                ch++;
                floodFill(grid, tmp[0], tmp[1], '2');
            }
        }
        return ch;
    }
