class Solution {
public:
    bool isIsomorphic(string s, string t) {
        // Use hashmaps to save the replacement for every character in the first string...
        unordered_map <char , char> rep;
        unordered_map <char , bool> used;
        // Traverse all elements through the loop...
        for(int idx = 0 ; idx < s.length() ; idx++) {
            // If rep contains s[idx] as a key...
            if(rep.count(s[idx])) {
                // Check if the rep is same as the character in the other string...
                // If not, the strings can’t be isomorphic. So, return false...
                if(rep[s[idx]] != t[idx])
                    return false;
            }
            // If no replacement found for first character, check if the second character has been used as the replacement for any other character in the first string...
            else {
                if(used[t[idx]])
                    return false;
                // If there exists no character whose replacement is the second character...
                // Assign the second character as the replacement of the first character.
                rep[s[idx]] = t[idx];
                used[t[idx]] = true;
            }
        }
        // Otherwise, the strings are not isomorphic.
        return true;
    }
};,120,https://leetcode.com/problems/isomorphic-strings,https://leetcode.com/problems/isomorphic-strings/solutions/2472118/very-easy-100-fully-explained-java-c-python-javascript-python3-using-hashmap/,75,205,cpp

import java.util.Hashtable;
class Solution {
    public static boolean isIsomorphic(String s, String t) {
        if (s.length() != t.length()) return false;

        Hashtable<Character , Character> hashtable = new Hashtable<>();
        for (int i = 0; i < s.length(); i++) 
        {
            char c1 = s.charAt(i);
            char c2 = t.charAt(i);

            if (hashtable.containsKey(c1))
            {
                if (hashtable.get(c1) != c2) return false;
            }else {
                if (hashtable.containsValue(c2)) return false;
                hashtable.put(c1 , c2);
            }
        }

        return true;
    }
