        unordered_map<char,string> m;
        set<string> used;
        for(int i=0;i<pattern.size();i++){
            if(m.find(pattern[i])!=m.end()){
                if(m[pattern[i]]!=v[i])
                return false;
            }
            else{
                if(used.count(v[i])>0)
                return false;
                m[pattern[i]]=v[i];
                used.insert(v[i]);

            }
        }
        return true;


    }
