class Solution {
public:
    int ans = 0 ;
    int solve(int prev ,int index,vector<int> &nums,vector<vector<int>> &dp)
    {
        if(index == nums.size())
             return  0 ; 

        if(dp[prev+1][index] != -1)
           return dp[prev+1][index] ; 

        if(prev == -1 || nums[prev] < nums[index])
            return dp[prev+1][index] =  max(solve(prev ,index + 1, nums, dp), 1 + solve(index , index + 1, nums, dp)) ;
        else
            return dp[prev+1][index] = solve(prev, index+1, nums, dp) ;
    }
    int lengthOfLIS(vector<int>& nums) 
    {
        int n = nums.size() ;
        vector<vector<int>> dp(n+1,vector<int> (n+1,-1)) ;

        return solve(-1,0,nums,dp) ;
    }
