class Solution {
public:
    int lengthOfLIS(vector<int>& nums) 
    {
        int n = nums.size() ;
        vector<int> dp ;

        dp.push_back(nums[0]) ;

        for(int index = 1 ; index < n ; index++)
        {
            int s = 0 ;
            int e = dp.size()-1 ;

            while(s <= e)
            {
                int mid = s + (e-s)/2;

                if(dp[mid] < nums[index])
                   s = mid + 1 ;
                else
                   e = mid - 1 ;
            }
            if(s < dp.size())
                dp[s] = nums[index] ;
            else 
                dp.push_back(nums[index]) ;
        }

        return dp.size() ;
    }
