class Solution {
public:
    bool isLeftNodeLeaf(TreeNode* root) {
        if(root == NULL)
            return false;

        if(root->left == NULL && root->right == NULL)
            return true;


        return false;
    } 

    void helper(TreeNode* root,int& sum) {
        if(root == NULL)
            return;

        if(isLeftNodeLeaf(root->left)) {
            sum += root->left->val;
        }

        helper(root->left,sum);
        helper(root->right,sum);
    }

    int sumOfLeftLeaves(TreeNode* root) {
       if(root == NULL)
        return 0;

        int sum = 0;
        helper(root,sum);

        return sum;
    }
