        int j = num2.size() - 1;
        int x = 0;
        while(i >= 0 && j >= 0){
            int d1 = num1[i] - '0';
            int d2 = num2[j] - '0';
            int t = d1 + d2 + x;
            if(t >= 10){
                x = 1;
                t = t%10;
            }
            else{
                x = 0;
            }
            char c = t + '0';
            ans += c;
            i--;
            j--;
        }
        while(i >= 0){
            int t = num1[i] - '0';
            t += x;
            if(t >= 10){
                t = t%10;
                x = 1;
            }
            else{
                x = 0;
            }
            ans += t + '0';
            i--;
        }
        while(j >= 0){
            int t = num2[j] - '0';
            t += x;
            if(t >= 10){
                t = t%10;
                x = 1;
            }
            else{
                x = 0;
            }
            ans += t + '0';
            j--;
        }
        if(x == 1) ans += '1';
        reverse(ans.begin(),ans.end());
