            bool found=false;
            while(idx<nums.Length && !found){
                if(nums[idx]>nums[i]){
                    ans[i]=nums[idx];
                    found=true;
                }
                idx++;
            }
            idx=0;
            while(idx<i && !found){
                if(nums[idx]>nums[i]){
                    ans[i]=nums[idx];
                    found=true;
                }
                idx++;
            }
            if(!found)
                ans[i]=-1;
        }
        return ans;
    }
