let findRotateSteps = (ring, key, m = new Map()) => {
    let M = ring.length,
        N = key.length;
    let steps = (i, k) => {
        let x = Math.abs(i - k);
        return Math.min(x, M - x); // ⭐️ minimum x steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
    };
    let pre = Array(M).fill(0); // 🤔 memo + 🛑 base case
    for (let j = N - 1; 0 <= j; --j) {     // key j
        let cur = Array(M).fill(Infinity);
        for (let i = 0; i < M; ++i)        // cur i
            for (let k = 0; k < M; ++k)    // pre i (optimal k-th value is found as the recursive stack unwinds)
                if (ring[k] == key[j])
                    cur[i] = Math.min(cur[i], 1 + steps(i, k) + pre[k]); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
        pre = [...cur];
    }

    return pre[0]; // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/,175,514,javascript

class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
        if (root == nullptr) {
            return vector<int>{};
        }

        vector<int> ans;
        stack<pair<TreeNode*, int>> stack;
        stack.push(make_pair(root, 0));

        while (!stack.empty()) {
            pair<TreeNode*, int> pair = stack.top();
            stack.pop();
            TreeNode* node = pair.first;
            int depth = pair.second;

            if (depth == ans.size()) {
                ans.push_back(node->val);
            } else {
                ans[depth] = max(ans[depth], node->val);
            }

            if (node->left) {
                stack.push(make_pair(node->left, depth + 1));
            }

            if (node->right) {
                stack.push(make_pair(node->right, depth + 1));
            }
        }

        return ans;
    }
};
