     bool canFormByDeleting(string word, string str) {
        int word_i = 0, str_i = 0;

        while (word_i < word.size() && str_i < str.size()) {

            if (word[word_i] == str[str_i])
                word_i++; 

            str_i++;
        }

        return word_i == word.size();
    }

