int Solution::findPairs(vector<int>& nums, int k) {
    int count=0;
    if (k == 0) {
        int i, size=nums.size();
        map<int,int> m;
        map<int,int>::iterator itm;
        for (i = 0; i < size; ++i) {
            ++m[nums[i]];
        }
        for (itm = m.begin(); itm != m.end(); ++itm) {
            if (itm->second > 1) {
                ++count;
            }
        }
        return count;
    }
    set<int> s(nums.begin(), nums.end());
    set<int>::iterator it1, it2, ref1 = s.end(), ref2;
    --ref1;
    for (it1 = s.begin(); it1 != ref1; ++it1) {
        ref2 = it1;
        ++ref2;
        for(it2 = ref2; it2 != s.end(); ++it2) {
            if (*it2-*it1 == k) {
                ++count;
            } else if (*it2-*it1 > k ) {
                break;
            }
        }
    }
    return count;
}
