class Solution {
public:
    string reverseWords(string s) {
        int n = s.size(); // Get the size of the input string.
        int i = 0, j = 0; // Initialize two pointers, 'i' and 'j', to track word boundaries.

        while (i < n) { // Iterate through the string until 'i' reaches the end.
            while (j < n && s[j] != ' ') j++; // Move 'j' to the end of the current word.

            // Reverse the characters of the current word using the reverse function.
            reverse(s.begin() + i, s.begin() + j);

            i = j + 1; // Move 'i' to the start of the next word.
            j = i;     // Reset 'j' to match 'i' for the next word.
        }

        return s; // Return the modified string with reversed words.
    }
};


