        for(int i=0;i<s1.size();i++){
            arr[s1[i]-'a']++;
        }
        while(j<s2.size()){
            brr[s2[j++]-'a']++;
            if(isPermutation(arr,brr)) return true;
            while(isContains(arr,brr) and i<=j){
                brr[s2[i++]-'a']--;
                if(isPermutation(arr,brr)) return true;
            }
        }
        return false;
    }
