class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        if(s1.size()>s2.size()){
            return false;
        }

        vector<int> alphabets1(26 , 0) , alphabets2(26 , 0) ;

        for(int i=0 ; i < s1.size() ; i++){
            alphabets1[s1[i]-'a']++;
            alphabets2[s2[i]-'a']++;
        }

        int matches=0 ;

        for(int i = 0 ; i<26 ; i++){
            if(alphabets1[i]==alphabets2[i]){
                matches++;
            }
        }

        int low = 0 ;

        for(int high = s1.size() ; high<s2.size() ; high++){
            if(matches == 26){
                return true;
            }

            if(s2[high] == s2[low]){
                low++;
                continue;
            }

            int index = s2[high] - 'a' ;
            alphabets2[index]++;
            if(alphabets1[index] == alphabets2[index]){
                matches++;
            }
            if(alphabets1[index]+1 == alphabets2[index]){
                matches--;
            }

            index = s2[low] - 'a';
            alphabets2[index]--;
            if(alphabets1[index] == alphabets2[index]){
                matches++;
            }
            if(alphabets1[index]-1 == alphabets2[index]){
                matches--;
            }

            low++;

        }
        return matches == 26;
    }
};,113,https://leetcode.com/problems/permutation-in-string,https://leetcode.com/problems/permutation-in-string/solutions/4211379/o-n-c-step-by-step-explanation/,203,567,cpp

