class Solution {

    int[][] dir = {{1,0},{-1,0},{0,1},{0,-1}};
    int MOD = 1000000007;

    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        int[][] dp = new int[m][n];
        dp[startRow][startColumn] = 1;
        int paths = 0;

        for(int move=1; move<=maxMove; move++){
            int[][] temp = new int[m][n];

            for(int i=0; i<m; i++){
                for(int j=0; j<n; j++){

                    if(dp[i][j] == 0) // if not updated in last move skip
                        continue;

                    for(int[] d : dir){ // try all directions

                        int x = i + d[0];
                        int y = j + d[1];

                        if(x == m || y == n || x == -1 || y == -1){ // if out of boundary get path
                            paths += dp[i][j] % MOD;
                            paths %= MOD;
                        }
                        else{
                            temp[x][y] += dp[i][j] % MOD; // else add the ways to reach this cell (i,j) in last move as ways to reach adjacent cell in this move
                            temp[x][y] %= MOD;
                        }
                    }
                }
            }
            dp = temp; //update dp with latest point reachable in this move
        }
        return (paths % MOD);
    }
