var scheduleCourse = function (courses) {
  // duration, endDate
  courses.sort((courses, b) => courses[1] - b[1]); // sort endDate asc

  let currtime = 0;
  let goodCourseDurations = [];
  for (let [duration, endDate] of courses) {
    if (currtime + duration <= endDate) {
      goodCourseDurations.push(duration);
      currtime += duration;
    } else {
      // max pq is best to use here
      let maxd = Math.max(...goodCourseDurations);
      if (maxd > duration) {
        let maxdIndex = goodCourseDurations.indexOf(maxd);
        goodCourseDurations[maxdIndex] = duration;

        currtime -= maxd;
        currtime += duration;
      }
    }
  }
  return goodCourseDurations.length;
