class trie{
    public:
    node* root=new node();

    void insert(string key){
        node* r1=root;
        for(auto ele:key){

            if(!r1->ispresent(ele)){
                r1->create(ele,new node());    
            }

            r1=r1->v[ele-'a'];
        }

        r1->setend();
    }

    bool func(string s,int j,node* rm){

        for(j;j<s.size();j++){
            if(!rm->ispresent(s[j]))return false;

            rm=rm->v[s[j]-'a'];
        }

        return rm->end;
    }


    bool search(string s){
        node* r1=root;
        int a=0;

        for(int j=0;j<s.size();j++){

             for(int i=0;i<26;i++){
                if(r1->ispresent(char('a'+i)) && s[j]-'a'!=i){
                    if(func(s,j+1,r1->v[i]))return true;   
                }
             }   

            if(r1->ispresent(s[j]))r1=r1->v[s[j]-'a'];
