class Solution {
private:
    vector<int> par;
    vector<int> rank;
    int findPar(int a)
    {
        if(a == par[a])
            return a;
        return par[a] = findPar(par[a]);
    }
    bool unionSet(int a,int b)
    {
        a = findPar(a);
        b = findPar(b);
        if(a == b)
            return false;
        if(rank[a] < rank[b])
        {
            par[a] = b;
        }
        else if(rank[a] > rank[b])
        {
            par[b] = a;
        }
        else
        {
            par[b] = a;
            rank[a]++;
        }
        return true;
    }
public:
    vector<int> findRedundantConnection(vector<vector<int>>& E) {
        int n = E.size();
        par.resize(n);
        rank.resize(n);
        for(int i=0;i<n;i++)
        {
            par[i] = i;
            rank[i] = 0;
        }
        for(int i=0;i<n;i++)
        {
            int a = E[i].front()-1;
            int b = E[i].back()-1;
            if(!unionSet(a,b))
               return {a+1,b+1}; 
        }
        return {};
    }
};,33,https://leetcode.com/problems/redundant-connection,https://leetcode.com/problems/redundant-connection/solutions/1295926/c-java-python-union-find-feel-free-to-reuse-clean-concise-o-n/,228,684,cpp

class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        struct Data {
            int count = 0;
            int firstIdx = -1;
            int lastIdx = -1;
        };

        unordered_map<int, Data> mp;
        int n = nums.size();
        int maxDeg = 0;

        for (int i=0; i<n; i++) {
            if (!mp.count(nums[i])) mp[nums[i]].firstIdx = i; // storing first-index
            mp[nums[i]].lastIdx = i; // updating last-index
            maxDeg = max(maxDeg, ++mp[nums[i]].count); // updating max-frequency
        }

        int res = n;
        for (const auto &[num, data]: mp) {
            if (data.count == maxDeg) {
                res = min(res, data.lastIdx - data.firstIdx + 1); 
            }
        }

        return res;
    }
