class Solution {
public:
    vector<int> asteroidCollision(vector<int>& a) {
        stack<int> s;
        vector<int> ans , temp;
        for(int i = 0 ; i < a.size();i++){
            if(a[i] < 0 && s.empty()){
                temp.push_back(a[i]);
                continue;
            }
            if(a[i] > 0){
                s.push(a[i]);
            }
            if(a[i] < 0){
                if(s.top() < 0){
                    s.push(a[i]);
                    continue;
                }
                int t = s.top();
                s.pop();
                if(t > a[i]*-1){
                    s.push(t);
                }
                else if(t == a[i]*-1) continue;
                else{
                    while(!s.empty() && t < a[i]*-1 && s.top() > 0){
                        t = s.top();
                        s.pop();
                    }
                    if(t > a[i]*-1){
                        s.push(t);
                    }
                    else if(t == a[i]*-1){
                        continue;
                    }
                    else s.push(a[i]);
                }
            }
        }
        while(!s.empty()){
            ans.push_back(s.top());
            s.pop();
        }
        reverse(ans.begin(),ans.end());
        for(int i = 0; i < ans.size();i++){
            temp.push_back(ans[i]);
        }
        return temp;
    }
};,54,https://leetcode.com/problems/asteroid-collision,https://leetcode.com/problems/asteroid-collision/solutions/3831014/solution-using-stack-beats-99-3/,241,735,cpp

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& T) {
        stack<int> s;
        vector<int> ans(size(T));
        for(int cur = size(T)-1; cur >= 0; cur--) {
		// pop till current temp > stack top's temp. All popped element can never be next warmer day for any other elements
            while(size(s) and T[s.top()] <= T[cur]) s.pop(); 
            ans[cur] = s.empty() ? 0 : s.top() - cur;   // no warmer element exists if stack empty. Otherwise, assign distance between stack's top and cur day
            s.push(cur);                                // push onto stack as it can potentially be next warmer day for rest elements
        }
        return ans;
    }
