class Solution {
public:
    bool backspaceCompare(string s, string t) {
        int nS=0, nT=0;
        while (!s.empty() || !t.empty()){
            while(!s.empty()){
                if (s.back()=='#') nS++, s.pop_back();
                else if (nS>0) nS--, s.pop_back();
                else break;
            }
            while(!t.empty()){
                if (t.back()=='#') nT++, t.pop_back();
                else if (nT>0) nT--, t.pop_back();
                else break;
            }
            if (!s.empty()&& !t.empty() &&s.back()!=t.back()) return 0;
            if ((s.empty()&&!t.empty())||(!s.empty()&&t.empty()))
                return 0;
            if (!s.empty())s.pop_back();
            if (!t.empty())t.pop_back();
        }
        return 1;
    }
};
