    int scoreOfParentheses(string s) {
        stack<string>st;
        for(auto ch: s){
            if(ch == '(') st.push("(");
            else{
                int temp = 0;
                while(st.top() != "("){
                    temp += (stoi(st.top()));
                    st.pop();
                }
                st.pop();
                if(temp == 0) st.push("1");
                else st.push(to_string(2 * temp));
            }
        }
        int ans = 0;
        while(!st.empty()){
            ans += stoi(st.top());
            st.pop();
        }
        return ans;
    }
