// Important points to remember while giving a try to this problem !
// -> Start a BFS from root
// -> Traverse to left,right and to its parent
// -> Store the parent of each node in a unordered_map using simple DFS
// -> Store all the values present in level cnt==k in a vector ans and simply return it.


class Solution {
public:
    // implementing the dfs 
    unordered_map<TreeNode*, TreeNode*> mp; // node, parent

    void DFS(TreeNode* root, TreeNode* parent){
        if(!root)return;
        if(!parent) parent = root;
        else mp[root] = parent;
        DFS(root->left,root);
        DFS(root->right,root);
    }

    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        // for bfs we'll be using queue DS
        queue<TreeNode*> q;
        set<TreeNode*> st;
        // populate all node,parent
        DFS(root,NULL);
        q.push(target);
        int cnt = 0;
        vector<int>ans;
        while(!q.empty()){
            int size = q.size();
            if(cnt>k)break;
            while(size--){
                auto node = q.front();
                q.pop();
                if(node->left && !st.count(node->left)){
                    q.push(node->left);
                    st.insert(node->left);
                }
                if(node->right && !st.count(node->right)){
                    q.push(node->right);
                    st.insert(node->right);
                }
                if(mp.count(node) && !st.count(mp[node])){
                    q.push(mp[node]);
                    st.insert(mp[node]);
                }
                st.insert(node);
                if(cnt==k){
                    ans.push_back(node->val);
                }
            }
            cnt++;
        }

       return ans; 
    }
