    public List<TreeNode> fbt(int n)
    {
        if(n==1)
        {
            ArrayList<TreeNode> leaf=new ArrayList();
            leaf.add(new TreeNode(0));
            return leaf;
        }
         List<TreeNode> ans=new ArrayList();
        for(int i=1;i<n;i+=2)
        {
             List<TreeNode> left=fbt(i);
             List<TreeNode> right=fbt(n-i-1);
            for(TreeNode l:left)
            {
                for(TreeNode r:right)
                {
                    TreeNode root=new TreeNode(0);
                    root.left=l;
                    root.right=r;
                    ans.add(root);
                }
            }

        }
        return ans;
    }
