class RLEIterator {
public:
    int idx;
    vector<int>v;
    RLEIterator(vector<int>& encoding) 
    {
        idx = 0;
        v = encoding;
    }

    int next(int n) 
    {
        while(idx < v.size()-1 and (v[idx] == 0 or v[idx] < n))
        {
            n = n - v[idx];
            idx = idx + 2;
        }  

        if(idx >= v.size()-1)
        return -1;

        if(idx < v.size()-1 and v[idx] > n)
        {
            v[idx] = v[idx] - n;
            return v[idx+1];
        }
        else if(idx < v.size()-1 and v[idx] == n)
        {
            int ele = v[idx+1];
            v[idx] = v[idx] - n;
            idx = idx + 2;
            return ele;
        }
        return -1;
    }
};

