class Solution {
public: 
    int Mod=1e9+7;
    bool check(int nRow, int nCol){
        if(nRow>=0&&nRow<4&&nCol>=0&&nCol<3)return true;
        return false;
    }
    int knightDialer(int n) {
        if(n==1)return 10;
        vector<vector<int>> phone(4,vector<int>(3,0));
        phone[0][0]=1;
        phone[0][1]=2;
        phone[0][2]=3;
        phone[1][0]=4;
        phone[1][1]=5;
        phone[1][2]=6;
        phone[2][0]=7;
        phone[2][1]=8;
        phone[2][2]=9;
        phone[3][0]=INT_MAX;
        phone[3][1]=0;
        phone[3][2]=INT_MAX;
        int ans=0;
        vector<vector<int>> dp(10,vector<int>(n+1,0));
        int Drow[8]={1,1,-1,-1,2,2,-2,-2};
        int Dcol[8]={2,-2,2,-2,-1,1,-1,1};

        for(int i=0; i<10; i++){
            dp[i][1] = 1;
        }

        for(int curr_jumps=2; curr_jumps<=n; curr_jumps++){
            for(int i=0; i<4; i++){
                for(int j=0; j<3; j++){
                    if(phone[i][j]==INT_MAX)continue;
                    else {
                        int sum=0;
                        for(int k=0; k<8; k++){
                            int nRow=i+Drow[k];
                            int nCol=j+Dcol[k];
                            if(check(nRow,nCol) && phone[nRow][nCol]!=INT_MAX){
                                sum= (sum+dp[phone[nRow][nCol]][curr_jumps-1])%Mod;
                            }
                        }
                        dp[phone[i][j]][curr_jumps]=sum%Mod;
                    }
                }
            }
        }

        for(int i=0; i<10; i++){
            ans+= dp[i][n];
            ans=ans%Mod;
        }
        return ans;
    }
};,188,https://leetcode.com/problems/knight-dialer,https://leetcode.com/problems/knight-dialer/solutions/4333745/4-solutions-memoization-1-memoization-2-tabulation-1-tabulation-1-tc-o-n-tc-o-n/,273,972,cpp

var movesToStamp = function(S, T) {
    if (S === T) return [0]
    let slen = S.length, tlen = T.length - slen + 1,
        ans = [], tdiff = true, sdiff, i, j
    S = S.split(""), T = T.split("")
    while (tdiff)
        for (i = 0, tdiff = false; i < tlen; i++) {
            for (j = 0, sdiff = false; j < slen; j++)
                if (T[i+j] === "*") continue
                else if (T[i+j] !== S[j]) break
                else sdiff = true
            if (j === slen && sdiff) {
                for (j = i, tdiff = true; j < slen + i; j++)
                    T[j] = "*"
                ans.unshift(i)
            }
        }
    for (i = 0; i < T.length; i++) if (T[i] !== "*") return []
    return ans
