class Solution {
public:
    TreeNode* insertIntoMaxTree(TreeNode* root, int val) {
        if(!root)return new TreeNode(val);
        else if(root->val<val){
            TreeNode* head=new TreeNode(val);
            head->left=root;
            return head;
        }else{
            root->right=insertIntoMaxTree(root->right,val);
            return root;
        }

    }
