class Solution {


    public static int calculator(ArrayList<String> arr) {
        int ans = 0;
        for(int i=0; i<arr.size(); i++){
            String s = arr.get(i);

            if(s.equals("*") || s.equals("/") || s.equals("%")){
                int a = Integer.valueOf(arr.remove(i-1));
                String op = arr.remove(i-1);
                int b = Integer.valueOf(arr.remove(i-1));

                if(op.equals("*")) ans = a*b;
                else if(op.equals("/")){
                    if(b==0){
                        System.out.println("Can't divide by 0");
                        return -1;
                    }
                    ans = a/b;
                }else ans=a%b;

                arr.add(i-1,String.valueOf(ans));
                i--;
            }

            if(i==arr.size()-2) break;
        }
        while(arr.size()!=1){

            int a = Integer.valueOf(arr.remove(0));
            String s = arr.remove(0);
            int b = Integer.valueOf(arr.remove(0));


            if(s.equals("+")) ans = a+b;
            else if(s.equals("-")) ans = a-b;
            else if(s.equals("*")) ans = a*b;
            else ans = a/b;

            arr.add(0,String.valueOf(ans));
        }

        return Integer.valueOf(arr.get(0));
    }

    public int clumsy(int n) {

        ArrayList<String> arr = new ArrayList<>();
        int idx = 1;
        arr.add(String.valueOf(n));
        for(int i=n-1; i>0; i--){
            if(idx==5) idx = 1;

            if(idx==1){
                arr.add("*");
                arr.add(String.valueOf(i));
            }else if(idx==2){
                arr.add("/");
                arr.add(String.valueOf(i));
            }else if(idx==3){
                arr.add("+");
                arr.add(String.valueOf(i));
            }else{
                arr.add("-");
                arr.add(String.valueOf(i));
            }
            idx++;
        }

        return calculator(arr);
    }
