class Solution {
    public int bitwiseComplement(int n) {
        if(n==0) return 1;
        int x = 0;
        int ans = 0;

        while(n>0){
            int r = n%2;
            if(r==1){
                x++;
            }else{
                ans = ans + (int)Math.pow(2,x);
                x++;
            }
            n=n/2;
        }
        return ans;
    }
