class Solution {
public:
    vector<int>parent,size;
    int m,n;
    void make(int i,int j)
    {
        parent[(n*i)+j]=(n*i)+j;
        size[(n*i)+j]=1;
        return;
    }
    int findparent(int var)
    {
        if(var==-1)
        {
            return -1;
        }
        if(parent[var]==var)
        {
            return var;
        }
        parent[var]=findparent(parent[var]);
        return parent[var];
    }
    void Union(int var1,int var2)
    {
        var1=findparent(var1);
        var2=findparent(var2);
        if(var1==var2)
        {
            return;
        }
        if(size[var1]>size[var2])
        {
            parent[var2]=var1;
            size[var1]+=size[var2];
        }
        else
        {
            parent[var1]=var2;
            size[var2]+=size[var1];
        }
        return;
    }
    int numEnclaves(vector<vector<int>>& board) 
    {
        m=board.size();
        n=board[0].size();
        int i,j;
        parent.assign(m*n,-1);
        size.assign(m*n,0);
        int ans=0;
        for(i=0;i<m;i++)
        {
            for(j=0;j<n;j++)
            {
                if(board[i][j]==1)
                {
                    ans++;
                    make(i,j);
                }
            }
        }
        for(i=0;i<m;i++)
        {
            for(j=0;j<n;j++)
            {
                if(board[i][j]==1)
                {
                    if(i>0 && board[i-1][j]==1)
                    {
                        Union(i*n+j,(i-1)*n+j);
                    }
                    if(j>0 && board[i][j-1]==1)
                    {
                        Union(i*n+j,i*n+j-1);
                    }
                    if(i<m-1 && board[i+1][j]==1)
                    {
                        Union(i*n+j,(i+1)*n+j);
                    }
                    if(j<n-1 && board[i][j+1]==1)
                    {
                        Union(i*n+j,i*n+j+1);
                    }
                }
            }
        }
        for(i=0;i<parent.size();i++)
        {
            parent[i]=findparent(i);
        }
        unordered_set<int>connectedatedges;
        for(i=0;i<m;i++)
        {
            if(board[i][0]==1)
            {
                connectedatedges.insert(parent[i*n]);
            }
            if(board[i][n-1]==1)
            {
                connectedatedges.insert(parent[(i+1)*n-1]);
            }
        }
        for(j=0;j<n;j++)
        {
            if(board[0][j]==1)
            {
                connectedatedges.insert(parent[j]);
            }
            if(board[m-1][j]==1)
            {
                connectedatedges.insert(parent[(m-1)*n+j]);
            }
        }
        for(auto k:connectedatedges)
        {
            ans-=size[k];
        }
        return ans;
    }
