class Solution {
public:
    string smallestSubsequence(string text) {
        vector<int> freq(26,0);
        vector<int> vis(26,0);
        stack<char> st;
        for(auto it:text) freq[it-'a']++;
        for(int i=0;i<text.size();i++){
            char c=text[i];
            freq[c-'a']--;
            if(vis[c-'a']) continue;
            while(!st.empty() && st.top()>c && freq[st.top()-'a']>0){
                vis[st.top()-'a']--;
                st.pop();
            }
            vis[c-'a']++;
            st.push(c);
        }
        string str="";
        while(!st.empty()){
            str=str+st.top();
            st.pop();
        }
        reverse(str.begin(),str.end());
        return str;
    }
