#include<cmath>
class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        int level=0,a=label;
        vector<int> res;
        while(a>0){a=a/2;level++;}
        for(int i=level-1;i>0;i--){
            res.push_back(label);
            int x=(pow(2,i)+pow(2,i-1)-1);
            int y=label/2;
            label=x-y;
        }
        res.push_back(1);
        reverse(res.begin(),res.end());
        return res;
    }
