class Solution {
    public String defangIPaddr(String address) {
        // declare ip to hold replacement
        String ip = "[.]";
        // declare dot to compare with char's in address string
        char dot = '.';
        // declare string builde to hold result
        StringBuilder result = new StringBuilder();
        // iterate over address string:
        for(int i = 0; i < address.length(); i++) {
            // get current character
            char ch = address.charAt(i);
            // check if it is a dot:
            if(ch == dot) {
                // if true append ip (replacement)
                result.append(ip);
            } else {
                // if false append current character
                result.append(ch);
            }
        }
        // return string from string builder
        return result.toString();
    }
