/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* lcaDeepestLeaves(TreeNode* root) 
{
   TreeNode* leftmost=NULL;
   TreeNode* rightmost=NULL;

   queue<TreeNode*>q;
   q.push(root);   //1  -->  last n     ...     0  -->  n-1

   while(!q.empty())
   {
   	  int size = q.size();

      for(int i=0;i<size;i++) 	  
      {
      	 TreeNode* temp = q.front();
      	 q.pop();

    	 if(i==0)
    	 {
    	 	leftmost = temp;
		 }
		 if(i==size-1)
		 {
		 	rightmost = temp;
		 }

		 if(temp->left)
		 q.push(temp->left);

		 if(temp->right)
		 q.push(temp->right);
	  }
   }
   vector<TreeNode*>path1;
   vector<TreeNode*>result1;
   lca(root,leftmost,path1,result1);

   vector<TreeNode*>path2;
   vector<TreeNode*>result2;
   lca(root,rightmost,path2,result2);

   int idx1=0;
   int idx2=0;

   while(idx1<result1.size() and idx2<result2.size())
   {
   	 if(result1[idx1]->val ==  result2[idx2]->val)
   	 {
   	    idx1++;
		idx2++;	
     }
     else 
     {
     	return result1[idx1-1];  //return result2[idx2-1]
	 }
   }
   return rightmost;
}
void lca(TreeNode* root,TreeNode* target,vector<TreeNode*>&path,vector<TreeNode*>&result)
{
   if(root==NULL)
   {
   	 return;
   }
   path.push_back(root);

   if(result.size()==0)
   lca(root->left,target,path,result);

   if(result.size()==0)
   lca(root->right,target,path,result);

   if(root->left==NULL and root->right==NULL and root->val==target->val and result.size()==0)
   {
      //need to store the resuilt        	
      result = path;
   }
   path.pop_back();
}
};,145,https://leetcode.com/problems/lowest-common-ancestor-of-deepest-leaves,https://leetcode.com/problems/lowest-common-ancestor-of-deepest-leaves/solutions/2748383/c-easy-short/,323,1218,cpp

