public:
    int maxRepOpt1(string text) {
        unordered_map<char, int> m, w;
        for(char c : text) m[c]++;

        int n = text.size(), i = 0, ans = 0;
        for(int j=0; j<n; j++) {
            w[text[j]]++;
            m[text[j]]--;
            if(!m[text[j]]) m.erase(text[j]);

            while(!good(w, m)) {
                w[text[i]]--;
                m[text[i]]++;
                if(!w[text[i]]) w.erase(text[i]);
                i++;
            }
            ans = max(ans, j - i + 1);
        }
        return ans;
    }
