var countSquares = function (matrix) {
  let dp = new Array(matrix.length).fill().map(() => {
    return new Array(matrix[0].length).fill(0);
  });
  let ans = 0;
  for (let i = 0; i < dp.length; i++) {
    for (let j = 0; j < dp[0].length; j++) {
      if (matrix[i][j] == 0) {
        //do not do anything
      } else if (i == 0 || j == 0) {
        dp[i][j] = 1;
        ans += dp[i][j];
      } else {
        let side = Math.min(
          dp[i - 1][j],
          Math.min(dp[i - 1][j - 1], dp[i][j - 1])
        );
        dp[i][j] = side + 1;
        ans += dp[i][j];
      }
    }
  }
  return ans;
};,81,https://leetcode.com/problems/count-square-submatrices-with-all-ones,https://leetcode.com/problems/count-square-submatrices-with-all-ones/solutions/4234704/clean-javascript-code-dp-on-matrix/,347,1402,javascript

class Solution {
    public int countSquares(int[][] matrix) {
        int n = matrix.length;
        int m = matrix[0].length;
        int[][] dp = new int[n][m];

        for(int i = 0; i < m; i++) dp[0][i] = matrix[0][i];
        for(int i = 0; i < n; i++) dp[i][0] = matrix[i][0];

        for(int i = 1; i < n; i++) {
            for(int j = 1; j < m; j++) {
                if(matrix[i][j] == 1) dp[i][j] = 1 + Math.min(Math.min(dp[i][j-1], dp[i-1][j]), dp[i-1][j-1]);
            }
        }

        int ans = 0;
        for(int[] arr : dp) {
            for(int ele : arr) {
                ans += ele;
            }
        }
        return ans;
    }
}

