class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        //one of the best of the best dp with bitmasking problem itself to understand dp with bitmask

         int m=seats.size();//rows
        int n=seats[0].size();//columns
        vector<int> validity(m+1);//remember we are taking m+1 not m
        //so first row is the 1th row not 0th
        for(int i=0;i<m;i++){
            int rowvalid=0;
            for(int j=0;j<n;j++){
                if(seats[i][j]=='.'){
                    rowvalid+=(1<<j);
                }
            }
            validity[i+1]=rowvalid;
        }

        //dp
        vector<vector<int>> dp(m+1,vector<int>((1<<n)+1,-1));
        //dp[i][j] represents the maximum number of students that can be placed till the ith row from the first row satisfying the condition that they cant cheat where j is the configuration of seated students in the ith row which satisfies the optimal result till this row
        dp[0][0]=0;//initializing
        for(int i=1;i<=m;i++){
            //go through each row
            int valid=validity[i];
            for(int j=0;j<(1<<n);j++){
                //go through the configuration of seats,total configurations 1<<n i.e 2^n
                if((j&valid)!=j){
                    continue;//j must be a subset of valid
					//valid contains the valid configuraion of avaliable seats where students can be placed for this ith row,
					//if the given configuration of students i.e "j" itself is invalid which means it isn't a subset of the "valid" then continue
                }
                if((j&(j>>1))){
                    continue;//no two students must be adjacent,given in the question
                }
                for(int k=0;k<(1<<n);k++){
                    if(dp[i-1][k]==-1){
                        continue;//invalid state
                    }
                    if((j&(k>>1)) || (k&(j>>1))){
                        continue;//checking if upper right and upper left seats are occupied which will lead to cheating
                    }
                    //reaching this state all the constraints are satisfied
                    dp[i][j]=max(dp[i][j],dp[i-1][k]+__builtin_popcount(j));
                }
            }
        }
        return *max_element(dp[m].begin(),dp[m].end());//last row
    }
