        Node* temp=new Node();
        temp->val=url;
        curr->next=temp;
        temp->prev=curr;
        curr=temp;
    }

    string back(int steps) {
        while(curr->prev && steps>0)
        {
            curr=curr->prev;
            steps--;
        }
        return curr->val;

    }

    string forward(int steps) {
       while(curr->next&& steps>0)
       {
           curr=curr->next;
           steps--;
       } 
       return curr->val;
    }
};

