class BrowserHistory {
public:
    vector<string> arr;
    int n=-1;
    BrowserHistory(string homepage) {
        arr.clear();
        arr.push_back(homepage);
        n=0;
    }

    void visit(string url) {
        if(n<arr.size()-1)
            arr.erase(arr.begin()+n+1, arr.begin()+arr.size());
        arr.push_back(url);
        n = arr.size()-1;
    }

    string back(int steps) {
        if((n-steps)>=0)
        {
            n -= steps;
            return arr[n];
        }
        else
        {
            n = 0;
            return arr[n];
        }
    }

    string forward(int steps) {
        if((n+steps)<arr.size())
        {
            n += steps;
            return arr[n];
        }
        else
        {
            n = arr.size()-1;
            return arr[n];
        }
    }
};

