const int MOD=1e9+7;
class Solution {
public:
    long long powr(long long a,long long b){
        long long res=1;
        while(b){
            if(b&1) res=(res*a)%MOD;
            a=(a*a)%MOD;
            b=b>>1;
        }
        return res;
    }
    int lowerBound(vector<int>& nums,int target){
        int n=nums.size();
        int s=0,e=n-1,res=n;
        while(s<=e){
            int mid=s+(e-s)/2;
            if(nums[mid]==target){
                res=mid;
                s=mid+1;
            }
            else if(nums[mid]<target){
                res=mid;
                s=mid+1;
            }
            else{
                e=mid-1;
            }
        }
        return res;
    }
    int numSubseq(vector<int>& nums, int target) {
        int n=nums.size();
        long long res=0;
        sort(nums.begin(),nums.end());
        for(int i=0;i<n;i++){
            int num=target-nums[i];
            int idx=lowerBound(nums,num);
            if(idx<n){
                if(idx>=i){
                    res=(res+powr(2,idx-i))%MOD;
                }
            }
        }
        return (int)res;
    }
};,109,https://leetcode.com/problems/number-of-subsequences-that-satisfy-the-given-sum-condition,https://leetcode.com/problems/number-of-subsequences-that-satisfy-the-given-sum-condition/solutions/3491364/daily-leetcode-solution-easy-c-solution/,409,1621,cpp

class Solution {
public:
    int numSubseq(vector<int>& nums, int target) {
        const int mod=1e9+7;
        sort(nums.begin(), nums.end());

        int n=nums.size();       
        vector<int> pow2mod(n+1, 1);
        for (int exp=1; exp<=n; exp++)
            pow2mod[exp]=(pow2mod[exp-1]<<1)%mod;

        int l=0, r=n-1;
        int result=0;
        while(l<=r){
            if( nums[l]+nums[r]<=target){
                result=(result+pow2mod[r-l])%mod;
                l++;
            }
            else r--;
        }
        return result;
    }
