class Solution {
public:
    int ans = 0 ;
    vector<int> solve(TreeNode* root , int d){
        //get distances in vectors from both the left and right 
        if(!root) return {} ;
        if(!root->left and !root->right) return {1} ;
        auto left = solve(root->left,d) ;
        auto right = solve(root->right,d) ;

        vector<int> temp ;

        for(auto &x : left) temp.push_back(x + 1) ;
        for(auto &x : right) temp.push_back(x + 1) ;

        for(auto &x : left)
            for(auto &y : right) ans += (x + y <= d) ? 1 : 0 ;

        return temp ;
    }
