class Solution {
public:
    // time/space: O(n)/O(1)
    int getWinner(vector<int>& arr, int k) {
        int n = arr.size();
        int arr0 = arr[0];
        int win_count = 0;
        for (int i = 1; i < n; i++) {
            if (arr0 > arr[i]) {
                win_count++;
            }
            else {
                arr0 = arr[i];
                win_count = 1;
            }
            if (win_count == k) return arr0;
        }
        return *max_element(arr.begin(), arr.end());
    }
