class Solution {
public:
    void toggle(char &ch) {
        if (ch == '1')
            ch = '0';
        else
            ch = '1';
    }

    char findKthBit(int n, int k) {
        int low = 0;
        int high = pow(2, n) - 2;
        char ch = '1';

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (mid == k - 1)
                break;
            else if (mid < k - 1) {
                ch = '0';
                low = mid + 1;
            } else {
                ch = '1';
                high = mid - 1;
            }
        }

        if (low == high) {
            toggle(ch);
        }

        return ch;
    }
