// Author: github.com/lzl124631x
// Time: O(N)
// Space: O(N)
class Solution {
public:
    char findKthBit(int n, int k) {
        if (n == 1) return '0';
        int len = pow(2, n) - 1;
        if (k - 1 == len / 2) return '1';
        if (k - 1 < len / 2) return findKthBit(n - 1, k);
        return findKthBit(n - 1, len - k + 1) == '0' ? '1' : '0';
    }
