class Solution {
public:
    int minSubarray(vector<int>& nums, int p) {
        long long int sum=0;
        for(int i=0;i<nums.size();i++){
            sum+=nums[i];
        }

        int rem=sum%p;
        if(rem==0)return 0;

        int ans=nums.size();
        unordered_map<int,int>m;
        sum=0;

        for(int i=0;i<nums.size();i++){
            sum+=nums[i];
            int rem2=sum%p;

            if(rem2==rem)
                ans=min(ans,i+1);

            if(m.find(rem2-rem)!=m.end()){
                ans=min(ans,i-m[rem2-rem]);
            }

            if(m.find(p+rem2-rem)!=m.end()){
                ans=min(ans,i-m[p+rem2-rem]);
            }
            m[rem2]=i;
        }
        if(ans>=nums.size())return -1;
        return ans;

    }
};

