class Solution {
public:
    vector<int> getSumAbsoluteDifferences(vector<int>& nums) {
        int n = nums.size();

        // Calculate the prefix sum of the input array 'nums'
        vector<int> prefix = {nums[0]};
        for (int i = 1; i < n; i++) {
            prefix.push_back(prefix[i - 1] + nums[i]);
        }

        vector<int> ans;
        for (int i = 0; i < n; i++) {
            // Calculate the sum of elements to the left and right of the current element
            int leftSum = prefix[i] - nums[i];
            int rightSum = prefix[n - 1] - prefix[i];

            // Calculate the count of elements to the left and right of the current element
            int leftCount = i;
            int rightCount = n - 1 - i;

            // Calculate the absolute difference sums for left and right parts
            int leftTotal = leftCount * nums[i] - leftSum;
            int rightTotal = rightSum - rightCount * nums[i];

            // Calculate the total sum of absolute differences for the current element
            ans.push_back(leftTotal + rightTotal);
        }

        return ans;
    }
