class Solution {
public:

    bool checkPartitioning(string s) {
        int n = s.size();
        int isp[n+1][n+1];
        memset(isp,0,sizeof(isp));
        for(int k = 0;k<n;k++)
        {
            int i = 0,j = k;
            while(i<n && j<n)
            {
                int diff = abs(i-j);
                if(diff==0) isp[i][j] = 1;
                else if(diff==1) isp[i][j] = s[i]==s[j];
                else if(s[i]==s[j] && isp[i+1][j-1]==1) isp[i][j] = 1;

                i++;
                j++;
            }
        }
        for(int k = 1;k<n-1;k++)
        {
            int i = 1,j = k;
            while(i<n && j<n)
            {
               if(isp[i][j]==1 && isp[0][i-1]==1 && isp[j+1][n-1]==1) return true; 

               i++;
               j++; 
            }
        }
        return false;
    }
