            {
                if (one == -100 && two == -100) {
                    one = s1.charAt(i) - 'a';
                    two = s2.charAt(i) - 'a';
                }
                else
                {
                    one -= s2.charAt(i) - 'a';
                    two -= s1.charAt(i) - 'a';
                }
            }
        }
        return one == 0 && two == 0;
    }
