class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<int> score(1 << n, 0);
        for (int i = 0; i < n; i++){
            for (int j = i + 1; j < n; j++){
                score[(1 << i) | (1 << j)] = __gcd(nums[i], nums[j]);
            }
        }
        vector<int> dp(1 << n, 0);
        for (int i = 1; i <= n / 2; i++){
            for (int w = (1 << (2 * i)) - 1; w < (1 << n); w = nextPerm(w)){
                for (int s = w; s; s = (s - 1) & w) if (__builtin_popcount(s) == 2){
                    dp[w] = max(dp[w], dp[w - s] + i * score[s]);
                }
            }
        }
        return dp[(1 << n) - 1];

    }

    inline int nextPerm(int v) {
        int t = v | (v - 1);
        return (t + 1) | (((~t & -~t) - 1) >> (__builtin_ctz(v) + 1));
    }
};,80,https://leetcode.com/problems/maximize-score-after-n-operations,https://leetcode.com/problems/maximize-score-after-n-operations/solutions/3521625/c-python-dynamic-programming-bitmask/,473,1906,cpp

class Solution {
public:
    long long c(long long n){
        return (n*(n+1))/2;
    }
    int maxValue(int n, int index, int maxSum) {
        long long l=1,r=maxSum;
        long long ans=1;
        while(l<=r){
            long long mid=(l+r)/2;
            long long left = c(mid-1);
            if(index>mid-1){
                left += (index-mid+1);
            }
            else left -= c(mid-1-index);
            long long right = c(mid-1) ;
            if((n-1-index)>(mid-1)){
                right += (n-1-index-(mid-1));
            }
            else right -= c(mid-1-(n-1-index));
            if(left+right<=(maxSum-mid)){
                ans=mid;
                l=mid+1;
            }
            else r=mid-1;
        }   
        return ans;
    }
};,98,https://leetcode.com/problems/maximum-value-at-a-given-index-in-a-bounded-array,https://leetcode.com/problems/maximum-value-at-a-given-index-in-a-bounded-array/solutions/3620614/c-binary-search/,474,1929,cpp

class Solution {
public:

    string evaluate(string s, vector<vector<string>>& k) {

        unordered_map<string,string>mpp;

        for(auto &it : k) mpp[it[0]] = it[1];

        string res = "";

        string temp;

        bool flag = 0;

        for(int i = 0; i < s.length(); ++i)
        {

           if(s[i] == '(') flag = 1;

           else if(s[i] == ')')
           {

               if(mpp[temp] == "") res += "?";

               else res += mpp[temp];

               flag = 0; temp = "";
           }

           else if(flag == 1) temp.push_back(s[i]);

           else res.push_back(s[i]);

        }

        return res;
    }
};

